typedef struct {fox_bg_context context;FILE *file;uint64_t events;} bg_observer_context;
static bool bg_range_overlap(const void*a,size_t an,const void*b,size_t bn){uintptr_t x=(uintptr_t)a,y=(uintptr_t)b;return an&&bn&&(x>UINTPTR_MAX-an||y>UINTPTR_MAX-bn||(x<=y&&y-x<an)||(y<=x&&x-y<bn));}
static bool bg_overlap(void *p,const void *q,size_t n){bg_observer_context*c=p;return !c||bg_range_overlap(c,sizeof*c,q,n)||fox_bg_context_overlaps(&c->context,q,n);}
static bool bg_compose_observed(void *p,const KsnSceneQuery*q,KsnSceneResult*out){
 bg_observer_context*c=p;if(!c||!c->file||!q||!out)return false;KsnSceneResult candidate={0};
 if(!fox_bg_compose(&c->context,q,&candidate))return false;const fox_bg_result*r=&c->context.last_result;
 if(fprintf(c->file,"{\"x\":%u,\"y\":%u,\"sample\":%u,\"characterHit\":%s,\"characterDepth\":%.9g,\"action\":%u,\"floorClassification\":%u,\"floorDepth\":%.17g,\"missReason\":%u,\"triangle\":%u,\"positiveQueries\":%llu,\"blockedQueries\":%llu",q->x,q->y,q->sample,q->character_hit?"true":"false",(double)q->character_depth,candidate.action,candidate.floor_classification,candidate.floor_native_depth,r->miss_reason,r->triangle,(unsigned long long)r->positive_queries,(unsigned long long)r->blocked_queries)<0)return false;
 const double *v[]={r->position,r->normal,r->direct,r->world,r->emission,r->combined,candidate.linear_rgb};const char*n[]={"P","Ng","direct","world","Le","combined","returnedRGB"};
 for(unsigned i=0;i<7;i++)if(fprintf(c->file,",\"%s\":[%.17g,%.17g,%.17g]",n[i],v[i][0],v[i][1],v[i][2])<0)return false;
 if(fputs("}\n",c->file)==EOF)return false;c->events++;*out=candidate;return true;
}
static const fox_bg_fixed_input*bg_select_input(const float cam[9],unsigned ci,bool reverse,uint64_t snapshot){
 const fox_bg_fixed_input*found=NULL;for(unsigned i=0;i<20;i++){const fox_bg_fixed_input*r=&fox_bg_inputs[i];if(r->case_index!=ci||r->reverse!=(unsigned)reverse||r->snapshot!=snapshot)continue;bool same=true;for(unsigned k=0;k<9;k++)if((double)cam[k]!=r->camera[k])same=false;if(same){if(found)return NULL;found=r;}}return found;
}
